ALTER TABLE jobs ADD COLUMN source_event_owned boolean NOT NULL DEFAULT false;
CREATE INDEX source_group_jobs_feed ON jobs(kind,feed_id,problem_code) WHERE problem_code LIKE 'source-%' AND octet_length(problem_code)<=1000 AND coalesce(octet_length(feed_id),0)<=1000;
CREATE INDEX reader_source_group_identity ON reader_problems ((body::jsonb->>'source_group_identity')) WHERE finished IS NULL AND octet_length(body::jsonb->>'source_group_identity')<=1000;
DROP INDEX jobs_unmanaged_problems;
CREATE INDEX jobs_unmanaged_problems ON jobs(kind,item) WHERE kind IS DISTINCT FROM 'read' AND kind IS DISTINCT FROM 'discover' AND problem_code IS DISTINCT FROM 'processor-config' AND NOT (kind IN ('delete','feed-delete') AND coalesce(nullif(problem_code,''),'work-'||kind) IN ('delete','feed-delete','work-delete','work-feed-delete')) AND NOT (kind IS NOT DISTINCT FROM 'fetch' AND item IS NOT NULL AND item<>'' AND problem_code IS NOT NULL AND problem_code NOT LIKE 'source-%' AND problem_code NOT IN ('codex-choice','ai-permission','youtube-admission','processor-config','identity-unconfirmed','profile_not_configured','profile_unavailable','account_identity_mismatch')) AND (problem_code IS NOT NULL OR error IS NOT NULL) AND NOT (kind IS NOT DISTINCT FROM 'download_media' AND item IS NOT NULL AND item<>'' AND problem_code IS NOT NULL AND problem_code NOT LIKE 'source-%' AND problem_code NOT IN ('codex-choice','ai-permission','youtube-admission','processor-config','identity-unconfirmed','profile_not_configured','profile_unavailable','account_identity_mismatch')) AND NOT ((kind IS NOT DISTINCT FROM 'filter' OR kind IS NOT DISTINCT FROM 'theses') AND item IS NOT NULL AND item<>'' AND (((problem_code='' OR (problem_code IS NULL AND error IS NOT NULL))) OR (problem_code IS NOT NULL AND problem_code<>'' AND problem_code NOT LIKE 'source-%' AND problem_code NOT IN ('codex-choice','ai-permission','youtube-admission','processor-config','identity-unconfirmed','profile_not_configured','profile_unavailable','account_identity_mismatch')))) AND NOT (kind IN ('fetch','download_media','filter','theses','delete','feed-delete') AND problem_code IS NOT NULL AND problem_code LIKE 'source-%' AND source_event_owned);
CREATE INDEX source_unowned_recovery ON jobs(id) WHERE kind IN ('fetch','download_media','filter','theses','delete','feed-delete') AND problem_code LIKE 'source-%' AND source_event_owned=false;
CREATE INDEX source_recovery_markers ON state (key text_pattern_ops) WHERE key LIKE 'source-recovery-seen:%';
CREATE INDEX source_youtube_timed ON state (key COLLATE "C") WHERE key LIKE 'source-youtube-timed:%';
CREATE INDEX source_legacy_protected ON state (key COLLATE "C") WHERE key LIKE 'source-legacy-protected:%';
